```python
"""Wallet holds, captures, voids, sweeps, refunds and fees.

Audit fixes relative to the previous revision:
- fee_for: integer arithmetic with ROUND_HALF_EVEN (was float + round-half-up).
- capture: replay is keyed on capture_id only and checked before state checks
  (previously keyed on hold_id, and captures were also stored under hold_id).
- capture: final=True now releases the uncaptured remainder to available.
- capture/refund/place_hold: amounts must be positive integers.
- sweep_expired: expires only when now > expires_at (inclusive expiry), and
  releases only the uncaptured remainder (previously released the full amount).
- refund: over-refund check is cumulative across parts.
- refund: fee_back is cumulative and rounded ROUND_HALF_EVEN, so the total fee
  returned always equals fee * total_refunded / captured rounded, and a full
  refund returns the fee exactly.
"""


class WalletError(Exception):
    pass


MIN_FEE = 30
FEE_BPS = 250
BPS_DENOM = 10000


def _div_half_even(numerator, denominator):
    """Integer division of a non-negative numerator by a positive denominator,
    rounding to nearest with ties to even."""
    q, r = divmod(numerator, denominator)
    twice = 2 * r
    if twice > denominator or (twice == denominator and q % 2 == 1):
        q += 1
    return q


def _check_amount(amount):
    if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
        raise WalletError("amount must be a positive integer")


def fee_for(amount):
    return max(MIN_FEE, _div_half_even(amount * FEE_BPS, BPS_DENOM))


class Wallet:
    def __init__(self):
        self.ledger = {}
        self.held = {}
        self.holds = {}
        self.captures = {}
        self.refunds = {}
        self.merchant = 0
        self.revenue = 0

    def deposit(self, account, amount):
        self.ledger[account] = self.ledger.get(account, 0) + amount

    def available(self, account):
        return self.ledger.get(account, 0) - self.held.get(account, 0)

    def _release_rest(self, hold):
        """Return the uncaptured remainder of a hold to available."""
        remaining = hold["amount"] - hold["captured"]
        if remaining:
            self.held[hold["account"]] -= remaining

    def place_hold(self, hold_id, account, amount, expires_at):
        if hold_id in self.holds:
            return self.holds[hold_id]
        _check_amount(amount)
        if self.available(account) < amount:
            raise WalletError("insufficient funds")
        hold = {
            "account": account,
            "amount": amount,
            "captured": 0,
            "status": "OPEN",
            "expires_at": expires_at,
        }
        self.holds[hold_id] = hold
        self.held[account] = self.held.get(account, 0) + amount
        return hold

    def capture(self, capture_id, hold_id, amount, now, final=False):
        if capture_id in self.captures:
            return self.captures[capture_id]
        hold = self.holds[hold_id]
        _check_amount(amount)
        if hold["status"] != "OPEN":
            raise WalletError("hold not open")
        if now > hold["expires_at"]:
            raise WalletError("hold expired")
        if hold["captured"] + amount > hold["amount"]:
            raise WalletError("over capture")
        fee = fee_for(amount)
        account = hold["account"]
        hold["captured"] += amount
        self.held[account] -= amount
        self.ledger[account] -= amount
        self.merchant += amount - fee
        self.revenue += fee
        record = {
            "capture_id": capture_id,
            "hold_id": hold_id,
            "amount": amount,
            "fee": fee,
            "refunded": 0,
            "fee_returned": 0,
        }
        self.captures[capture_id] = record
        if final:
            self._release_rest(hold)
            hold["status"] = "CLOSED"
        return record

    def void(self, hold_id):
        hold = self.holds[hold_id]
        if hold["status"] != "OPEN":
            return hold
        self._release_rest(hold)
        hold["status"] = "VOIDED"
        return hold

    def sweep_expired(self, now):
        expired = []
        for hold_id, hold in self.holds.items():
            if hold["status"] == "OPEN" and now > hold["expires_at"]:
                self._release_rest(hold)
                hold["status"] = "EXPIRED"
                expired.append(hold_id)
        return expired

    def refund(self, refund_id, capture_id, amount):
        if refund_id in self.refunds:
            return self.refunds[refund_id]
        capture = self.captures[capture_id]
        _check_amount(amount)
        new_refunded = capture["refunded"] + amount
        if new_refunded > capture["amount"]:
            raise WalletError("over refund")
        total_fee_back = _div_half_even(capture["fee"] * new_refunded, capture["amount"])
        fee_back = total_fee_back - capture["fee_returned"]
        account = self.holds[capture["hold_id"]]["account"]
        capture["refunded"] = new_refunded
        capture["fee_returned"] = total_fee_back
        self.ledger[account] += amount
        self.merchant -= amount - fee_back
        self.revenue -= fee_back
        record = {
            "refund_id": refund_id,
            "capture_id": capture_id,
            "amount": amount,
            "fee_back": fee_back,
        }
        self.refunds[refund_id] = record
        return record
